meaning_es":"conforme a; seguir (las reglas)"},{"source_order":10984,"hanzi":"琢磨","source_label":"琢磨","source_level_label":"7-9","pinyin":"zuómo","pinyin_plain":"zuomo","part_of_speech":"动","meaning_es":"ponderar; rumiar; pensar a fondo; pron. de Taiwán"},{"source_order":10985,"hanzi":"左顾右盼","source_label":"左顾右盼","source_level_label":"7-9","pinyin":"zuǒgù-yòupàn","pinyin_plain":"zuoguyoupan","part_of_speech":null,"meaning_es":"mirando a izquierda y derecha (modismo); mirar por todos lados"},{"source_order":10986,"hanzi":"作弊","source_label":"作弊","source_level_label":"7-9","pinyin":"zuòbì","pinyin_plain":"zuobi","part_of_speech":"动","meaning_es":"cometer fraude; hacer trampa; incurrir en prácticas corruptas"},{"source_order":10987,"hanzi":"作对","source_label":"作对","source_level_label":"7-9","pinyin":"zuòduì","pinyin_plain":"zuodui","part_of_speech":"动","meaning_es":"ponerse en contra de; oponerse; formar una pareja"},{"source_order":10988,"hanzi":"作废","source_label":"作废","source_level_label":"7-9","pinyin":"zuòfèi","pinyin_plain":"zuofei","part_of_speech":"动","meaning_es":"quedar sin validez; cancelar; borrar; anular"},{"source_order":10989,"hanzi":"作风","source_label":"作风","source_level_label":"7-9","pinyin":"zuòfēng","pinyin_plain":"zuofeng","part_of_speech":"名","meaning_es":"estilo; estilo de trabajo; modo"},{"source_order":10990,"hanzi":"作客","source_label":"作客","source_level_label":"7-9","pinyin":"zuòkè","pinyin_plain":"zuoke","part_of_speech":"动","meaning_es":"vivir en un lugar como visitante; alojarse con alguien como huésped; residir temporalmente"},{"source_order":10991,"hanzi":"作料","source_label":"作料","source_level_label":"7-9","pinyin":"zuòliao","pinyin_plain":"zuoliao","part_of_speech":"名","meaning_es":"condimentos; sazón; pronunciación coloquial; pronunciación de Taiwán"},{"source_order":10992,"hanzi":"坐落","source_label":"坐落","source_level_label":"7-9","pinyin":"zuòluò","pinyin_plain":"zuoluo","part_of_speech":"动","meaning_es":"estar situado; estar ubicado (un edificio)"},{"source_order":10993,"hanzi":"座谈","source_label":"座谈","source_level_label":"7-9","pinyin":"zuòtán","pinyin_plain":"zuotan","part_of_speech":"动","meaning_es":"tener una charla informal"},{"source_order":10994,"hanzi":"作为","source_label":"作为2","source_level_label":"7-9","pinyin":"zuòwéi","pinyin_plain":"zuowei","part_of_speech":"名、动","meaning_es":"la conducta de uno; acto; actividad; realización; logro; actuar como; como (en calidad de); en cuanto a; te…"},{"source_order":10995,"hanzi":"作物","source_label":"作物","source_level_label":"7-9","pinyin":"zuòwù","pinyin_plain":"zuowu","part_of_speech":"名","meaning_es":"cultivo"},{"source_order":10996,"hanzi":"作息","source_label":"作息","source_level_label":"7-9","pinyin":"zuòxī","pinyin_plain":"zuoxi","part_of_speech":"动","meaning_es":"trabajar y descansar"},{"source_order":10997,"hanzi":"座右铭","source_label":"座右铭","source_level_label":"7-9","pinyin":"zuòyòumíng","pinyin_plain":"zuoyouming","part_of_speech":"名","meaning_es":"lema; máxima"},{"source_order":10998,"hanzi":"作战","source_label":"作战","source_level_label":"7-9","pinyin":"zuòzhàn","pinyin_plain":"zuozhan","part_of_speech":"动","meaning_es":"combate; luchar"},{"source_order":10999,"hanzi":"做证","source_label":"做证","source_level_label":"7-9","pinyin":"zuòzhèng","pinyin_plain":"zuozheng","part_of_speech":"动","meaning_es":"testificar; dar testimonio"},{"source_order":11000,"hanzi":"做主","source_label":"做主","source_level_label":"7-9","pinyin":"zuòzhǔ","pinyin_plain":"zuozhu","part_of_speech":"动","meaning_es":"hacerse cargo; tomar la decisión"}]$catalog$::jsonb) as entry (
  source_order integer,
  hanzi text,
  source_label text,
  source_level_label text,
  pinyin text,
  pinyin_plain text,
  part_of_speech text,
  meaning_es text
);

insert into words (hanzi, hsk_level, hsk_version, origin, status)
select distinct hanzi, 7, '3.0', 'open_data'::content_origin, 'unreviewed'::review_status
from hsk_source_entries_temp
on conflict (hanzi) do nothing;

-- Reutiliza únicamente un sentido previo sin catálogo y todavía sin revisar.
-- Si el sentido fue curado, crea otro borrador en vez de apropiárselo.
with matched_entries as (
  select
    words.id as word_id,
    source_entries.*,
    count(*) over (partition by words.id, source_entries.pinyin) as matching_entry_count
  from hsk_source_entries_temp as source_entries
  join words using (hanzi)
), reusable as (
  select matched_entries.*, matched_sense.id as sense_id
  from matched_entries
  left join lateral (
    select senses.id
    from senses
    where senses.word_id = matched_entries.word_id
      and senses.pinyin = matched_entries.pinyin
      and senses.catalog_source_id is null
      and senses.status = 'unreviewed'
    order by senses.position
    limit 1
  ) as matched_sense on true
  where matched_entries.matching_entry_count = 1
)
update senses
set
  catalog_source_id = 'cti-hsk3-2026',
  catalog_source_order = reusable.source_order,
  pinyin_plain = coalesce(senses.pinyin_plain, reusable.pinyin_plain),
  category = coalesce(senses.category, reusable.part_of_speech),
  meaning_es = coalesce(senses.meaning_es, reusable.meaning_es)
from reusable
where senses.id = reusable.sense_id
  and reusable.sense_id is not null
  and senses.status = 'unreviewed';

with candidates as (
  select words.id as word_id, source_entries.*
  from hsk_source_entries_temp as source_entries
  join words using (hanzi)
  where not exists (
    select 1 from senses
    where senses.catalog_source_id = 'cti-hsk3-2026'
      and senses.catalog_source_order = source_entries.source_order
  )
), positioned as (
  select candidates.*,
    coalesce((select max(senses.position) from senses where senses.word_id = candidates.word_id), 0)
      + row_number() over (partition by candidates.word_id order by candidates.source_order) as position
  from candidates
)
insert into senses (
  word_id, position, pinyin, pinyin_plain, category, meaning_es,
  catalog_source_id, catalog_source_order, origin, status
)
select
  word_id, position, pinyin, pinyin_plain, part_of_speech, meaning_es,
  'cti-hsk3-2026', source_order, 'open_data'::content_origin, 'unreviewed'::review_status
from positioned
on conflict (word_id, position) do nothing;

insert into word_levels (
  word_id, sense_id, standard, level, source_id, source_order,
  source_label, source_level_label, pinyin, part_of_speech
)
select
  words.id, matched_sense.id, 'hsk-3.0', 7, 'cti-hsk3-2026',
  source_entries.source_order, source_entries.source_label,
  source_entries.source_level_label, source_entries.pinyin,
  source_entries.part_of_speech
from hsk_source_entries_temp as source_entries
join words using (hanzi)
left join lateral (
  select senses.id
  from senses
  where senses.catalog_source_id = 'cti-hsk3-2026'
    and senses.catalog_source_order = source_entries.source_order
  order by senses.position
  limit 1
) as matched_sense on true
on conflict (standard, source_order) do nothing;

drop table hsk_source_entries_temp;
